{{(function(){
  const src = appsmith.store.qcLogsModalSource;
  const row = src === "Qc_Table1" ? Qc_Table1.triggeredRow : Qc_Table.triggeredRow;
  let logs = row ? row.qc_logs : [];
  if (typeof logs === "string") {
    try { logs = JSON.parse(logs); } catch (e) { logs = []; }
  }
  if (!logs || !logs.length) {
    return "No QC attempts yet.";
  }
  return logs.map((log, i) => {
    const start = log.qc_start_time || "-";
    const end = log.qc_end_time || "In Progress";
    const tag = log.qc_tag || "-";
    const desc = log.qc_description || "-";
    const notes = log.qc_notes;
    let line = "Attempt " + (i + 1) + ": Start " + start + " | End " + end + " | Tag: " + tag + " | Description: " + desc;
    if (notes) {
      line += " | Remarks: " + notes;
    }
    return line;
  }).join("\n");
})()}}
